CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(btrim(name)) BETWEEN 2 AND 160), created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.organizations TO authenticated;
GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ADD COLUMN organization_id uuid REFERENCES public.organizations(id);
CREATE INDEX profiles_organization_idx ON public.profiles(organization_id);
INSERT INTO public.organizations(id,name) SELECT '00000000-0000-4000-8000-000000000001','Pôvodná organizácia' WHERE EXISTS(SELECT 1 FROM public.profiles);
UPDATE public.profiles SET organization_id='00000000-0000-4000-8000-000000000001' WHERE organization_id IS NULL;
CREATE OR REPLACE FUNCTION public.my_organization() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT organization_id FROM public.profiles WHERE id=auth.uid() $$;
CREATE OR REPLACE FUNCTION public.same_organization(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user AND organization_id=public.my_organization()) $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.organization_id=public.my_organization()) $$;
CREATE OR REPLACE FUNCTION public.is_manager_of(_emp uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_emp AND manager_id=auth.uid() AND organization_id=public.my_organization()) $$;
CREATE OR REPLACE FUNCTION public.can_see(_emp uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _emp=auth.uid() OR (public.same_organization(_emp) AND (public.is_manager_of(_emp) OR public.has_role(auth.uid(),'admin'))) $$;
CREATE POLICY organization_read ON public.organizations FOR SELECT TO authenticated USING(id=public.my_organization());
CREATE TABLE public.organization_invites (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id), code text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(24),'hex'));
GRANT SELECT ON public.organization_invites TO authenticated;
GRANT ALL ON public.organization_invites TO service_role;
ALTER TABLE public.organization_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invite_admin_read ON public.organization_invites FOR SELECT TO authenticated USING(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.organization_settings (organization_id uuid NOT NULL DEFAULT public.my_organization() REFERENCES public.organizations(id), key text NOT NULL, value text NOT NULL DEFAULT '', description text, PRIMARY KEY(organization_id,key));
GRANT SELECT,UPDATE ON public.organization_settings TO authenticated;
GRANT ALL ON public.organization_settings TO service_role;
ALTER TABLE public.organization_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_org_read ON public.organization_settings FOR SELECT TO authenticated USING(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY settings_org_update ON public.organization_settings FOR UPDATE TO authenticated USING(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin')) WITH CHECK(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.organization_codes (organization_id uuid NOT NULL DEFAULT public.my_organization() REFERENCES public.organizations(id), code text NOT NULL REFERENCES public.absence_codes(code), sap_code text NOT NULL, name text NOT NULL, calc_type text NOT NULL, counts boolean NOT NULL DEFAULT false, limit_days numeric, sort integer NOT NULL DEFAULT 0, PRIMARY KEY(organization_id,code));
GRANT SELECT,UPDATE ON public.organization_codes TO authenticated;
GRANT ALL ON public.organization_codes TO service_role;
ALTER TABLE public.organization_codes ENABLE ROW LEVEL SECURITY;
CREATE POLICY codes_org_read ON public.organization_codes FOR SELECT TO authenticated USING(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY codes_org_update ON public.organization_codes FOR UPDATE TO authenticated USING(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin')) WITH CHECK(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.organization_holidays (organization_id uuid NOT NULL DEFAULT public.my_organization() REFERENCES public.organizations(id), day date NOT NULL, name text NOT NULL, PRIMARY KEY(organization_id,day));
GRANT SELECT,INSERT,DELETE ON public.organization_holidays TO authenticated;
GRANT ALL ON public.organization_holidays TO service_role;
ALTER TABLE public.organization_holidays ENABLE ROW LEVEL SECURITY;
CREATE POLICY holidays_org_read ON public.organization_holidays FOR SELECT TO authenticated USING(organization_id=public.my_organization());
CREATE POLICY holidays_org_insert ON public.organization_holidays FOR INSERT TO authenticated WITH CHECK(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY holidays_org_delete ON public.organization_holidays FOR DELETE TO authenticated USING(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
INSERT INTO public.organization_settings SELECT o.id,s.* FROM public.organizations o CROSS JOIN public.settings s;
INSERT INTO public.organization_codes SELECT o.id,c.* FROM public.organizations o CROSS JOIN public.absence_codes c;
INSERT INTO public.organization_holidays SELECT o.id,h.* FROM public.organizations o CROSS JOIN public.holidays h;
INSERT INTO public.organization_invites(organization_id) SELECT id FROM public.organizations;
REVOKE ALL ON public.settings,public.absence_codes,public.holidays FROM authenticated,anon;
COMMENT ON TABLE public.settings IS 'DEPRECATED for client use: provisioning defaults; organization_settings is authoritative.';
COMMENT ON TABLE public.absence_codes IS 'DEPRECATED for client use: canonical codes and provisioning defaults; organization_codes is authoritative.';
COMMENT ON TABLE public.holidays IS 'DEPRECATED for client use: provisioning defaults; organization_holidays is authoritative.';
CREATE OR REPLACE FUNCTION public.calc_settings() RETURNS TABLE(key text,value text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.key,s.value FROM public.organization_settings s WHERE s.organization_id=public.my_organization() AND s.key IN ('ZAOKRUHLENIE_PRICHOD','ZAOKRUHLENIE_ODCHOD','OBED_PAUZA_MIN','OBED_PO_HODINACH','DENNY_FOND_HODIN','MAX_ODCHYLKA_CASU_MIN') $$;
ALTER POLICY "profiles admin update" ON public.profiles USING(public.same_organization(id) AND public.has_role(auth.uid(),'admin')) WITH CHECK(organization_id=public.my_organization() AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "roles read" ON public.user_roles USING(user_id=auth.uid() OR (public.same_organization(user_id) AND public.has_role(auth.uid(),'admin')));
ALTER POLICY "roles admin insert" ON public.user_roles WITH CHECK(public.same_organization(user_id) AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "roles admin delete" ON public.user_roles USING(public.same_organization(user_id) AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "closures admin delete" ON public.month_closures USING(public.same_organization(user_id) AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "closures insert" ON public.month_closures WITH CHECK(closed_by=auth.uid() AND public.same_organization(user_id) AND (public.is_manager_of(user_id) OR public.has_role(auth.uid(),'admin')));
ALTER POLICY "audit admin read" ON public.audit_log USING(public.same_organization(actor) AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "punches own insert" ON public.punches WITH CHECK(user_id=auth.uid() AND source='terminal' AND public.my_organization() IS NOT NULL);
ALTER POLICY "corr own insert" ON public.corrections WITH CHECK(user_id=auth.uid() AND status='pending' AND public.my_organization() IS NOT NULL AND NOT public.is_closed(user_id,at_time));
CREATE OR REPLACE FUNCTION public.guard_profile_organization() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN RAISE EXCEPTION 'Organizáciu účtu nemožno zmeniť'; END IF; IF NEW.manager_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.manager_id AND organization_id=NEW.organization_id) THEN RAISE EXCEPTION 'Manažér musí byť z rovnakej organizácie'; END IF; RETURN NEW; END $$;
CREATE TRIGGER profile_organization_guard BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_organization();
CREATE OR REPLACE FUNCTION public.guard_last_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; BEGIN IF OLD.role='admin' THEN SELECT organization_id INTO org FROM public.profiles WHERE id=OLD.user_id; PERFORM pg_advisory_xact_lock(hashtext(org::text)); IF NOT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.role='admin' AND p.organization_id=org AND r.id<>OLD.id) THEN RAISE EXCEPTION 'Organizácia musí mať aspoň jedného správcu'; END IF; END IF; RETURN OLD; END $$;
CREATE TRIGGER last_admin_guard BEFORE DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_last_admin();
CREATE OR REPLACE FUNCTION public.decide_correction(_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.corrections; BEGIN SELECT * INTO c FROM public.corrections WHERE id=_id FOR UPDATE; IF c.id IS NULL OR c.status<>'pending' THEN RAISE EXCEPTION 'Žiadosť neexistuje alebo je vybavená'; END IF; IF NOT(public.same_organization(c.user_id) AND (public.is_manager_of(c.user_id) OR public.has_role(auth.uid(),'admin'))) THEN RAISE EXCEPTION 'Nemáte oprávnenie'; END IF; UPDATE public.corrections SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,decided_by=auth.uid(),decided_at=now() WHERE id=_id; IF _approve THEN INSERT INTO public.punches(client_uuid,user_id,code,direction,client_time,source,device) VALUES(gen_random_uuid(),c.user_id,c.code,c.direction,c.at_time,'correction','schválil '||auth.uid()); END IF; INSERT INTO public.audit_log(actor,action,target,details) VALUES(auth.uid(),CASE WHEN _approve THEN 'correction_approved' ELSE 'correction_rejected' END,c.user_id::text,to_jsonb(c)); END $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; org_name text; invite text; BEGIN org_name:=btrim(COALESCE(NEW.raw_user_meta_data->>'organization_name','')); invite:=btrim(COALESCE(NEW.raw_user_meta_data->>'invite_code','')); IF org_name<>'' AND invite<>'' THEN RAISE EXCEPTION 'Vyberte registráciu firmy alebo pozvanie'; END IF; IF org_name<>'' THEN IF length(org_name) NOT BETWEEN 2 AND 160 THEN RAISE EXCEPTION 'Názov organizácie musí mať 2 až 160 znakov'; END IF; INSERT INTO public.organizations(name,created_by) VALUES(org_name,NEW.id) RETURNING id INTO org; INSERT INTO public.organization_settings SELECT org,s.* FROM public.settings s; INSERT INTO public.organization_codes SELECT org,c.* FROM public.absence_codes c; INSERT INTO public.organization_holidays SELECT org,h.* FROM public.holidays h; INSERT INTO public.organization_invites(organization_id) VALUES(org); ELSE SELECT organization_id INTO org FROM public.organization_invites WHERE code=invite; IF org IS NULL THEN RAISE EXCEPTION 'Neplatný pozývací kód organizácie'; END IF; END IF; INSERT INTO public.profiles(id,full_name,email,organization_id) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name',split_part(NEW.email,'@',1)),NEW.email,org); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'employee'); IF org_name<>'' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin'),(NEW.id,'manager'); END IF; RETURN NEW; END $$;
CREATE FUNCTION public.rotate_organization_invite() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Nemáte oprávnenie'; END IF; UPDATE public.organization_invites SET code=encode(gen_random_bytes(24),'hex') WHERE organization_id=public.my_organization() RETURNING code INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.my_organization(),public.same_organization(uuid),public.rotate_organization_invite() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_organization(),public.same_organization(uuid),public.rotate_organization_invite() TO authenticated,service_role;